function isPrime(n) {
    if (n <= 1) {
        return false;
    }
    if (n === 2) {
        return true;
    }
    if (n % 2 === 0) {
        return false;
    }
    let maxDivisor = Math.sqrt(n) + 1;
    for (let d = 3; d <= maxDivisor; d += 2) {
        if (n % d === 0) {
            return false;
        }
    }
    return true;
}

let primeNumbers = [];
for (let num = 2; num <= 100; num++) {
    if (isPrime(num)) {
        primeNumbers.push(num);
    }
}
console.log(primeNumbers);
```

